def generate_csv():
    os.makedirs("datasets", exist_ok=True)
    df = pd.DataFrame(DATASET_RECORDS, columns=["text", "category", "priority", "sentiment"])
    output_path = os.path.join("datasets", "grievances.csv")
    df.to_csv(output_path, index=False)
    print(f"Generated {len(df)} samples in {output_path}")
    print("\nCategory breakdown:\n", df["category"].value_counts())
    print("\nPriority breakdown:\n", df["priority"].value_counts())
    print("\nSentiment breakdown:\n", df["sentiment"].value_counts())

if __name__ == '__main__':
    generate_csv()
